/* ===== RedRoom Fitness — Global Styles ===== */
@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600;700&display=swap');

:root {
  --red: #FF0000;
  --red-dark: #CC0000;
  --red-glow: rgba(255, 0, 0, 0.3);
  --black: #141414;
  --black-light: #1E1E1E;
  --black-lighter: #2A2A2A;
  --white: #FFFFFF;
  --gray: #B0B0B0;
  --gray-dark: #666;
  --font-head: 'Oswald', sans-serif;
  --font-body: 'Inter', sans-serif;
  --transition: 0.3s ease;
  --max-width: 1200px;
}

*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: var(--font-body);
  background: var(--black);
  color: var(--white);
  line-height: 1.6;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

a {
  color: var(--white);
  text-decoration: none;
  transition: color var(--transition);
}

a:hover {
  color: var(--red);
}

img {
  max-width: 100%;
  display: block;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-head);
  text-transform: uppercase;
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: 0.02em;
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

/* ===== Top Bar Promo ===== */
.top-bar {
  background: var(--red);
  text-align: center;
  padding: 10px 24px;
  font-family: var(--font-head);
  text-transform: uppercase;
  font-size: 0.85rem;
  letter-spacing: 0.1em;
  font-weight: 500;
}

.top-bar a {
  color: var(--white);
  text-decoration: underline;
  margin-left: 8px;
  font-weight: 700;
}

.top-bar a:hover {
  color: var(--black);
}

/* ===== Navigation ===== */
.nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: var(--black);
  border-bottom: 1px solid var(--black-lighter);
}

.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.nav-logo {
  font-family: var(--font-head);
  font-size: 1.5rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--red);
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-logo .logo-icon {
  width: 32px;
  height: 32px;
  background: var(--red);
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  color: var(--white);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 28px;
  list-style: none;
}

.nav-links a {
  font-family: var(--font-head);
  font-size: 0.82rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-weight: 500;
  color: var(--gray);
  transition: color var(--transition);
  white-space: nowrap;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--white);
}

.nav-utility {
  display: flex;
  align-items: center;
  gap: 16px;
  list-style: none;
}

.nav-utility a {
  font-family: var(--font-head);
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 600;
  color: var(--white);
}

.nav-utility .btn-nav {
  background: var(--red);
  padding: 8px 18px;
  border-radius: 2px;
  font-weight: 700;
}

.nav-utility .btn-nav:hover {
  background: var(--red-dark);
  color: var(--white);
}

.nav-hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  background: none;
  border: none;
  padding: 4px;
}

.nav-hamburger span {
  width: 24px;
  height: 2px;
  background: var(--white);
  transition: var(--transition);
}

/* Mobile nav */
.nav-mobile {
  display: none;
  position: fixed;
  top: 64px;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--black);
  z-index: 999;
  padding: 32px 24px;
  overflow-y: auto;
}

.nav-mobile.open {
  display: block;
}

.nav-mobile a {
  display: block;
  font-family: var(--font-head);
  font-size: 1.2rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 14px 0;
  border-bottom: 1px solid var(--black-lighter);
  color: var(--gray);
}

.nav-mobile a:hover {
  color: var(--white);
}

/* ===== Hero Section ===== */
.hero {
  position: relative;
  min-height: 80vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 100px 24px 80px;
  background: radial-gradient(ellipse at center, rgba(255, 0, 0, 0.08) 0%, transparent 60%), var(--black);
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 2px,
    rgba(255, 0, 0, 0.015) 2px,
    rgba(255, 0, 0, 0.015) 4px
  );
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 800px;
}

.hero-content h1 {
  font-size: clamp(2.5rem, 6vw, 5rem);
  margin-bottom: 20px;
  color: var(--white);
}

.hero-content h1 .red {
  color: var(--red);
}

.hero-content p {
  font-size: 1.1rem;
  color: var(--gray);
  margin-bottom: 36px;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.hero-ctas {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* ===== Buttons ===== */
.btn {
  display: inline-block;
  font-family: var(--font-head);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 700;
  padding: 14px 36px;
  font-size: 0.9rem;
  border: none;
  cursor: pointer;
  transition: all var(--transition);
  text-align: center;
}

.btn-primary {
  background: var(--red);
  color: var(--white);
}

.btn-primary:hover {
  background: var(--red-dark);
  color: var(--white);
  transform: translateY(-2px);
  box-shadow: 0 8px 30px var(--red-glow);
}

.btn-outline {
  background: transparent;
  color: var(--white);
  border: 2px solid var(--white);
}

.btn-outline:hover {
  background: var(--white);
  color: var(--black);
  transform: translateY(-2px);
}

.btn-lg {
  padding: 18px 48px;
  font-size: 1rem;
}

/* ===== Section Styles ===== */
.section {
  padding: 100px 24px;
}

.section-dark {
  background: var(--black-light);
}

.section-red {
  background: var(--red);
  color: var(--white);
}

.section-red h2 {
  color: var(--white);
}

.section-heading {
  font-size: clamp(2rem, 4vw, 3.2rem);
  margin-bottom: 24px;
  text-align: center;
}

.section-subheading {
  font-size: 1.05rem;
  color: var(--gray);
  text-align: center;
  max-width: 600px;
  margin: 0 auto 48px;
}

/* ===== Community Promo ===== */
.community-promo {
  text-align: center;
}

.community-promo h2 {
  font-size: clamp(2.5rem, 5vw, 4rem);
  margin-bottom: 24px;
}

.community-promo p {
  font-size: 1.1rem;
  color: var(--gray);
  max-width: 700px;
  margin: 0 auto 36px;
  line-height: 1.8;
}

/* ===== Two Ways ===== */
.two-ways {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  max-width: 1000px;
  margin: 0 auto;
}

.way-card {
  background: var(--black-light);
  padding: 48px 36px;
  border: 1px solid var(--black-lighter);
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}

.way-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 4px;
  height: 100%;
  background: var(--red);
  transform: scaleY(0);
  transition: transform var(--transition);
  transform-origin: bottom;
}

.way-card:hover::before {
  transform: scaleY(1);
}

.way-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
}

.way-card .label {
  font-family: var(--font-head);
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--red);
  margin-bottom: 16px;
  font-weight: 600;
}

.way-card h3 {
  font-size: 1.8rem;
  margin-bottom: 16px;
}

.way-card p {
  color: var(--gray);
  line-height: 1.7;
}

/* ===== Studio Experience ===== */
.studio-experience {
  text-align: center;
  position: relative;
}

.studio-experience::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 300px;
  height: 300px;
  background: radial-gradient(circle, rgba(255, 0, 0, 0.1) 0%, transparent 70%);
  pointer-events: none;
}

.studio-experience h2 {
  font-size: clamp(2rem, 4vw, 3rem);
  margin-bottom: 20px;
  position: relative;
}

.studio-experience p {
  color: var(--gray);
  max-width: 700px;
  margin: 0 auto 36px;
  line-height: 1.8;
  position: relative;
}

/* ===== Free Trial CTA ===== */
.free-trial-cta {
  text-align: center;
  padding: 120px 24px;
  position: relative;
  overflow: hidden;
}

.free-trial-cta::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(135deg, rgba(255, 0, 0, 0.15) 0%, transparent 50%);
  pointer-events: none;
}

.free-trial-cta h2 {
  font-size: clamp(2.5rem, 5vw, 4.5rem);
  margin-bottom: 36px;
  position: relative;
}

.free-trial-cta .btn-primary {
  font-size: 1.1rem;
  padding: 20px 56px;
  position: relative;
  animation: pulse-glow 2s ease-in-out infinite;
}

@keyframes pulse-glow {
  0%, 100% { box-shadow: 0 0 20px rgba(255, 0, 0, 0.3); }
  50% { box-shadow: 0 0 40px rgba(255, 0, 0, 0.6); }
}

/* ===== Lifestyle Carousel ===== */
.carousel-section {
  padding: 80px 0;
  overflow: hidden;
}

.carousel-section .section-heading {
  margin-bottom: 40px;
  padding: 0 24px;
}

.carousel-wrapper {
  position: relative;
  max-width: 1000px;
  margin: 0 auto;
  padding: 0 60px;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.carousel-slide {
  min-width: 100%;
  aspect-ratio: 16/9;
  background: var(--black-light);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
  border-radius: 2px;
}

.carousel-slide-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.carousel-slide-overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 30px;
  background: linear-gradient(transparent, rgba(0,0,0,0.8));
}

.carousel-slide-overlay span {
  font-family: var(--font-head);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-size: 0.9rem;
  color: var(--red);
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: rgba(20, 20, 20, 0.85);
  border: 1px solid var(--black-lighter);
  color: var(--white);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all var(--transition);
  font-size: 1.2rem;
  z-index: 2;
}

.carousel-btn:hover {
  background: var(--red);
  border-color: var(--red);
}

.carousel-btn-prev { left: 8px; }
.carousel-btn-next { right: 8px; }

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 24px;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--black-lighter);
  cursor: pointer;
  transition: background var(--transition);
  border: none;
}

.carousel-dot.active {
  background: var(--red);
}

/* ===== Newsletter ===== */
.newsletter {
  background: var(--black-light);
  text-align: center;
  padding: 80px 24px;
}

.newsletter h2 {
  font-size: 1.6rem;
  margin-bottom: 12px;
}

.newsletter p {
  color: var(--gray);
  margin-bottom: 28px;
  font-size: 0.95rem;
}

.newsletter-form {
  display: flex;
  max-width: 480px;
  margin: 0 auto;
  gap: 0;
}

.newsletter-form input[type="email"] {
  flex: 1;
  padding: 14px 18px;
  background: var(--black);
  border: 1px solid var(--black-lighter);
  color: var(--white);
  font-family: var(--font-body);
  font-size: 0.9rem;
  outline: none;
  transition: border-color var(--transition);
}

.newsletter-form input[type="email"]:focus {
  border-color: var(--red);
}

.newsletter-form input[type="email"].error {
  border-color: #ff4444;
}

.newsletter-form input[type="email"].success {
  border-color: #00cc66;
}

.newsletter-form button {
  background: var(--red);
  color: var(--white);
  border: none;
  padding: 14px 28px;
  font-family: var(--font-head);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 700;
  font-size: 0.85rem;
  cursor: pointer;
  transition: background var(--transition);
}

.newsletter-form button:hover {
  background: var(--red-dark);
}

.newsletter-msg {
  max-width: 480px;
  margin: 12px auto 0;
  font-size: 0.85rem;
  min-height: 1.4em;
}

.newsletter-msg.error-msg {
  color: #ff4444;
}

.newsletter-msg.success-msg {
  color: #00cc66;
}

/* ===== Footer ===== */
.footer {
  background: var(--black);
  border-top: 1px solid var(--black-lighter);
  padding: 60px 24px 30px;
}

.footer-grid {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}

.footer-col h4 {
  font-family: var(--font-head);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--red);
  margin-bottom: 20px;
}

.footer-col ul {
  list-style: none;
}

.footer-col ul li {
  margin-bottom: 10px;
}

.footer-col ul li a {
  color: var(--gray);
  font-size: 0.88rem;
  transition: color var(--transition);
}

.footer-col ul li a:hover {
  color: var(--white);
}

.footer-country {
  position: relative;
  display: inline-block;
}

.footer-country-btn {
  background: var(--black-light);
  border: 1px solid var(--black-lighter);
  color: var(--gray);
  padding: 8px 16px;
  font-family: var(--font-head);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 8px;
}

.footer-country-btn:hover {
  border-color: var(--red);
  color: var(--white);
}

.footer-country-dropdown {
  display: none;
  position: absolute;
  bottom: 100%;
  left: 0;
  background: var(--black-light);
  border: 1px solid var(--black-lighter);
  min-width: 160px;
  margin-bottom: 4px;
  z-index: 10;
}

.footer-country-dropdown.open {
  display: block;
}

.footer-country-dropdown a {
  display: block;
  padding: 10px 16px;
  font-size: 0.85rem;
  color: var(--gray);
  transition: all var(--transition);
}

.footer-country-dropdown a:hover {
  background: var(--black-lighter);
  color: var(--white);
}

.footer-bottom {
  max-width: var(--max-width);
  margin: 0 auto;
  border-top: 1px solid var(--black-lighter);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
}

.footer-bottom p {
  color: var(--gray-dark);
  font-size: 0.8rem;
}

.footer-social {
  display: flex;
  gap: 16px;
}

.footer-social a {
  color: var(--gray-dark);
  font-size: 0.85rem;
  transition: color var(--transition);
}

.footer-social a:hover {
  color: var(--red);
}

/* ===== Method Overview ===== */
.method-overview {
  text-align: center;
}

.method-overview h2 {
  font-size: clamp(2.5rem, 5vw, 4rem);
  margin-bottom: 24px;
}

.method-overview p {
  color: var(--gray);
  max-width: 700px;
  margin: 0 auto;
  line-height: 1.8;
  font-size: 1.05rem;
}

/* ===== Weekly Schedule ===== */
.schedule-table {
  max-width: 800px;
  margin: 0 auto;
  width: 100%;
  border-collapse: collapse;
}

.schedule-table thead th {
  font-family: var(--font-head);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-size: 0.8rem;
  color: var(--red);
  padding: 16px 20px;
  text-align: left;
  border-bottom: 2px solid var(--red);
}

.schedule-table tbody td {
  padding: 16px 20px;
  border-bottom: 1px solid var(--black-lighter);
  font-size: 0.95rem;
}

.schedule-table tbody td:first-child {
  font-family: var(--font-head);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-weight: 600;
  color: var(--white);
}

.schedule-table tbody td:last-child {
  color: var(--gray);
}

.schedule-table tbody tr:hover {
  background: var(--black-light);
}

/* ===== Floor / Treadmill Toggle ===== */
.toggle-section {
  text-align: center;
}

.toggle-controls {
  display: inline-flex;
  margin-bottom: 40px;
  border: 1px solid var(--black-lighter);
  border-radius: 2px;
  overflow: hidden;
}

.toggle-btn {
  background: transparent;
  border: none;
  color: var(--gray);
  font-family: var(--font-head);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-size: 0.9rem;
  font-weight: 600;
  padding: 14px 36px;
  cursor: pointer;
  transition: all var(--transition);
}

.toggle-btn.active {
  background: var(--red);
  color: var(--white);
}

.toggle-btn:hover:not(.active) {
  color: var(--white);
  background: var(--black-lighter);
}

.toggle-content {
  display: none;
  max-width: 700px;
  margin: 0 auto;
  text-align: center;
  animation: fadeIn 0.3s ease;
}

.toggle-content.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.toggle-content h3 {
  font-size: 2rem;
  margin-bottom: 16px;
  color: var(--red);
}

.toggle-content p {
  color: var(--gray);
  line-height: 1.8;
  font-size: 1.05rem;
}

/* ===== Instructors ===== */
.instructor-filters {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-bottom: 48px;
  flex-wrap: wrap;
}

.filter-btn {
  background: transparent;
  border: 1px solid var(--black-lighter);
  color: var(--gray);
  font-family: var(--font-head);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 0.8rem;
  font-weight: 500;
  padding: 10px 22px;
  cursor: pointer;
  transition: all var(--transition);
}

.filter-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: var(--white);
}

.filter-btn:hover:not(.active) {
  border-color: var(--red);
  color: var(--white);
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.instructor-card {
  background: var(--black-light);
  border: 1px solid var(--black-lighter);
  overflow: hidden;
  transition: all var(--transition);
}

.instructor-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
}

.instructor-card-img {
  width: 100%;
  aspect-ratio: 3/4;
  background: linear-gradient(135deg, var(--black-lighter), var(--black-light));
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.instructor-card-img::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 60%;
  background: linear-gradient(transparent, rgba(20, 20, 20, 0.9));
}

.instructor-initials {
  font-family: var(--font-head);
  font-size: 2.5rem;
  color: var(--red);
  opacity: 0.3;
  text-transform: uppercase;
}

.instructor-card-body {
  padding: 20px;
}

