  padding: 10px 24px;
  font-family: var(--font-head);
  text-transform: uppercase;
  font-size: 0.85rem;
  letter-spacing: 0.1em;
  font-weight: 500;
}

.top-bar a {
  color: var(--white);
  text-decoration: underline;
  margin-left: 8px;
  font-weight: 700;
}

.top-bar a:hover {
  color: var(--black);
}

/* ===== Navigation ===== */
.nav {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: var(--black);
  border-bottom: 1px solid var(--black-lighter);
}

.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.nav-logo {
  font-family: var(--font-head);
  font-size: 1.5rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
