  gap: 8px;
}

.nav-logo .logo-icon {
  width: 32px;
  height: 32px;
  background: var(--red);
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  color: var(--white);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 28px;
  list-style: none;
}

.nav-links a {
  font-family: var(--font-head);
  font-size: 0.82rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-weight: 500;
  color: var(--gray);
  transition: color var(--transition);
  white-space: nowrap;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--white);
}

.nav-utility {
  display: flex;
  align-items: center;
  gap: 16px;
  list-style: none;
}

.nav-utility a {
  font-family: var(--font-head);
