/* ===== Community Promo ===== */
.community-promo {
  text-align: center;
}

.community-promo h2 {
  font-size: clamp(2.5rem, 5vw, 4rem);
  margin-bottom: 24px;
}

.community-promo p {
  font-size: 1.1rem;
  color: var(--gray);
  max-width: 700px;
  margin: 0 auto 36px;
