  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}

.footer-col h4 {
  font-family: var(--font-head);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--red);
  margin-bottom: 20px;
}

.footer-col ul {
  list-style: none;
}

.footer-col ul li {
  margin-bottom: 10px;
}

.footer-col ul li a {
  color: var(--gray);
  font-size: 0.88rem;
  transition: color var(--transition);
}

.footer-col ul li a:hover {
  color: var(--white);
}

.footer-country {
  position: relative;
  display: inline-block;
}

.footer-country-btn {
  background: var(--black-light);
  border: 1px solid var(--black-lighter);
  color: var(--gray);
  padding: 8px 16px;
  font-family: var(--font-head);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 8px;
}

.footer-country-btn:hover {
  border-color: var(--red);
  color: var(--white);
}

.footer-country-dropdown {
  display: none;
  position: absolute;
  bottom: 100%;
  left: 0;
  background: var(--black-light);
  border: 1px solid var(--black-lighter);
  min-width: 160px;
  margin-bottom: 4px;
  z-index: 10;
}

.footer-country-dropdown.open {
  display: block;
}

.footer-country-dropdown a {
  display: block;
  padding: 10px 16px;
  font-size: 0.85rem;
  color: var(--gray);
  transition: all var(--transition);
}

.footer-country-dropdown a:hover {
  background: var(--black-lighter);
  color: var(--white);
}

.footer-bottom {
  max-width: var(--max-width);
  margin: 0 auto;
  border-top: 1px solid var(--black-lighter);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
}

.footer-bottom p {
  color: var(--gray-dark);
  font-size: 0.8rem;
}

.footer-social {
  display: flex;
  gap: 16px;
}

.footer-social a {
  color: var(--gray-dark);
  font-size: 0.85rem;
  transition: color var(--transition);
}

.footer-social a:hover {
  color: var(--red);
}

/* ===== Method Overview ===== */
.method-overview {
  text-align: center;
}

.method-overview h2 {
  font-size: clamp(2.5rem, 5vw, 4rem);
  margin-bottom: 24px;
}

.method-overview p {
  color: var(--gray);
  max-width: 700px;
  margin: 0 auto;
  line-height: 1.8;
  font-size: 1.05rem;
}

/* ===== Weekly Schedule ===== */
.schedule-table {
  max-width: 800px;
  margin: 0 auto;
  width: 100%;
  border-collapse: collapse;
}

.schedule-table thead th {
  font-family: var(--font-head);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-size: 0.8rem;
  color: var(--red);
  padding: 16px 20px;
  text-align: left;
  border-bottom: 2px solid var(--red);
}

.schedule-table tbody td {
  padding: 16px 20px;
  border-bottom: 1px solid var(--black-lighter);
  font-size: 0.95rem;
}

.schedule-table tbody td:first-child {
  font-family: var(--font-head);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-weight: 600;
  color: var(--white);
}

.schedule-table tbody td:last-child {
  color: var(--gray);
}

.schedule-table tbody tr:hover {
  background: var(--black-light);
}

/* ===== Floor / Treadmill Toggle ===== */
.toggle-section {
  text-align: center;
}

.toggle-controls {
  display: inline-flex;
  margin-bottom: 40px;
  border: 1px solid var(--black-lighter);
  border-radius: 2px;
  overflow: hidden;
}

.toggle-btn {
  background: transparent;
  border: none;
  color: var(--gray);
  font-family: var(--font-head);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-size: 0.9rem;
  font-weight: 600;
  padding: 14px 36px;
  cursor: pointer;
  transition: all var(--transition);
}

.toggle-btn.active {
  background: var(--red);
  color: var(--white);
}

.toggle-btn:hover:not(.active) {
  color: var(--white);
  background: var(--black-lighter);
}

.toggle-content {
  display: none;
  max-width: 700px;
  margin: 0 auto;
  text-align: center;
  animation: fadeIn 0.3s ease;
}

.toggle-content.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.toggle-content h3 {
  font-size: 2rem;
  margin-bottom: 16px;
  color: var(--red);
}

.toggle-content p {
  color: var(--gray);
  line-height: 1.8;
  font-size: 1.05rem;
}

/* ===== Instructors ===== */
.instructor-filters {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-bottom: 48px;
  flex-wrap: wrap;
}

.filter-btn {
  background: transparent;
  border: 1px solid var(--black-lighter);
  color: var(--gray);
  font-family: var(--font-head);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 0.8rem;
  font-weight: 500;
  padding: 10px 22px;
  cursor: pointer;
  transition: all var(--transition);
}

.filter-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: var(--white);
}

.filter-btn:hover:not(.active) {
  border-color: var(--red);
  color: var(--white);
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.instructor-card {
  background: var(--black-light);
  border: 1px solid var(--black-lighter);
  overflow: hidden;
  transition: all var(--transition);
}

.instructor-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
}

.instructor-card-img {
  width: 100%;
  aspect-ratio: 3/4;
  background: linear-gradient(135deg, var(--black-lighter), var(--black-light));
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.instructor-card-img::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 60%;
  background: linear-gradient(transparent, rgba(20, 20, 20, 0.9));
}

.instructor-initials {
  font-family: var(--font-head);
  font-size: 2.5rem;
  color: var(--red);
  opacity: 0.3;
  text-transform: uppercase;
}

.instructor-card-body {
  padding: 20px;
}

.instructor-card-body h3 {
  font-size: 1.1rem;
  margin-bottom: 6px;
}

.instructor-card-body .location {
  color: var(--red);
  font-family: var(--font-head);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 0.72rem;
  margin-bottom: 14px;
}

.instructor-card-body .book-link {
  color: var(--gray);
  font-size: 0.85rem;
  font-weight: 500;
  transition: color var(--transition);
}

.instructor-card-body .book-link:hover {
  color: var(--red);
}

.instructor-card.hidden {
  display: none;
}

/* ===== FAQ Accordion ===== */
.faq-list {
  max-width: 760px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--black-lighter);
}

.faq-question {
  width: 100%;
  background: none;
  border: none;
  color: var(--white);
  font-family: var(--font-head);
  font-size: 1.1rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  text-align: left;
  padding: 24px 0;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: color var(--transition);
}

.faq-question:hover {
  color: var(--red);
}

.faq-question .icon {
  font-size: 1.4rem;
  transition: transform var(--transition);
  color: var(--red);
  flex-shrink: 0;
  margin-left: 16px;
}

.faq-item.open .faq-question .icon {
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}

.faq-answer-inner {
  padding-bottom: 24px;
  color: var(--gray);
  line-height: 1.8;
  font-size: 0.95rem;
}

/* ===== Digital Platform ===== */
.features-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 30px;
  max-width: 1000px;
  margin: 0 auto;
}

.feature-card {
  background: var(--black-light);
  border: 1px solid var(--black-lighter);
  padding: 40px 32px;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}

.feature-card::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 3px;
  background: var(--red);
  transform: scaleX(0);
  transition: transform var(--transition);
  transform-origin: left;
}

.feature-card:hover::after {
  transform: scaleX(1);
}

.feature-card:hover {
  border-color: var(--red);
  transform: translateY(-3px);
}

.feature-card h3 {
  font-size: 1.15rem;
  margin-bottom: 12px;
  color: var(--white);
}

.feature-card p {
  color: var(--gray);
  line-height: 1.7;
  font-size: 0.92rem;
}

.feature-card .feature-num {
  font-family: var(--font-head);
  font-size: 3rem;
  color: var(--red);
  opacity: 0.15;
  position: absolute;
  top: 16px;
  right: 20px;
  line-height: 1;
}

/* ===== CTA Sections ===== */
.cta-section {
  text-align: center;
  padding: 100px 24px;
}

.cta-section h2 {
  font-size: clamp(2rem, 4vw, 3rem);
  margin-bottom: 32px;
}

.cta-buttons {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* ===== Unlimited Access ===== */
.unlimited-section {
  text-align: center;
  position: relative;
}

.unlimited-section h2 {
  font-size: clamp(2rem, 4vw, 3.5rem);
  margin-bottom: 16px;
}

.unlimited-section p {
  color: var(--gray);
  max-width: 600px;
  margin: 0 auto 36px;
  font-size: 1.05rem;
  line-height: 1.8;
}

/* ===== Workout Types ===== */
.workout-types-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  max-width: 900px;
  margin: 0 auto;
}

.workout-type-card {
  background: var(--black-light);
  border: 1px solid var(--black-lighter);
  padding: 36px 24px;
  text-align: center;
  transition: all var(--transition);
}

.workout-type-card:hover {
  border-color: var(--red);
  transform: translateY(-3px);
}

.workout-type-card .type-icon {
  font-size: 2rem;
  color: var(--red);
  margin-bottom: 16px;
}

.workout-type-card h3 {
  font-size: 1rem;
  margin-bottom: 8px;
}

.workout-type-card p {
  color: var(--gray);
  font-size: 0.85rem;
  line-height: 1.6;
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .instructor-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .features-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .nav-links {
    display: none;
  }

  .nav-utility {
    display: none;
  }

  .nav-hamburger {
    display: flex;
  }
}

@media (max-width: 768px) {
  .hero {
    min-height: 70vh;
    padding: 80px 24px 60px;
  }

  .hero-content h1 {
    font-size: clamp(2rem, 8vw, 3rem);
  }

  .two-ways {
    grid-template-columns: 1fr;
  }

  .instructor-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .features-grid {
    grid-template-columns: 1fr;
  }

  .workout-types-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .carousel-wrapper {
    padding: 0 48px;
  }

  .free-trial-cta h2 {
    font-size: clamp(1.8rem, 6vw, 3rem);
  }

  .newsletter-form {
    flex-direction: column;
  }

  .newsletter-form button {
    width: 100%;
  }

  .schedule-table {
    font-size: 0.9rem;
  }

  .schedule-table thead th,
  .schedule-table tbody td {
    padding: 12px 14px;
  }
}

@media (max-width: 480px) {
  .instructor-grid {
    grid-template-columns: 1fr;
    max-width: 360px;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .hero-ctas {
    flex-direction: column;
    align-items: center;
  }

  .hero-ctas .btn {
    width: 100%;
    max-width: 300px;
  }

  .instructor-filters {
    gap: 6px;
  }

  .filter-btn {
    padding: 8px 14px;
    font-size: 0.72rem;
  }

  .toggle-btn {
    padding: 12px 20px;
    font-size: 0.8rem;
  }
}
